const WA_ICON =
  "M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.885-9.885 9.885M20.52 3.449C18.24 1.245 15.24 0 12.045 0 5.463 0 .104 5.359.101 11.892c0 2.096.549 4.14 1.595 5.945L0 24l6.335-1.652a11.882 11.882 0 005.71 1.454h.005c6.585 0 11.946-5.359 11.949-11.893 0-3.181-1.24-6.171-3.495-8.42";

const WaIcon = ({ className }) => (
  <svg viewBox="0 0 24 24" className={className} fill="currentColor" aria-hidden="true">
    <path d={WA_ICON} />
  </svg>
);

const waHref = (text) => `https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(text)}`;

export const WhatsAppButton = ({ className = "", testid = "whatsapp-cta", onClick }) => {
  const { t } = useTranslation();
  return (
    <a
      href={waHref(t("whatsapp.prefill"))}
      target="_blank"
      rel="noopener noreferrer"
      onClick={onClick}
      data-testid={testid}
      className={`inline-flex w-full items-center justify-center gap-2.5 px-5 py-3.5 rounded-2xl bg-[#25D366] hover:bg-[#1eb955] text-white font-bold text-base transition-colors ${className}`}
    >
      <WaIcon className="w-6 h-6 flex-none" />
      {t("whatsapp.cta")}
    </a>
  );
};

export const WhatsAppFab = ({ testid = "whatsapp-fab", onClick }) => {
  const { t } = useTranslation();
  return (
    <a
      href={waHref(t("whatsapp.prefill"))}
      target="_blank"
      rel="noopener noreferrer"
      onClick={onClick}
      data-testid={testid}
      aria-label={t("whatsapp.cta")}
      className="fixed z-50 bottom-5 right-4 inline-flex items-center gap-2 rounded-full bg-[#25D366] hover:bg-[#1eb955] text-white font-bold shadow-lg shadow-emerald-600/30 pl-3 pr-4 py-3 transition-colors"
    >
      <WaIcon className="w-6 h-6 flex-none" />
      <span className="hidden sm:inline text-sm">{t("whatsapp.fab")}</span>
    </a>
  );
};
